<?php
require_once "../config.php";
require_admin();
$title = "Laporan Bulanan";
$bulan = (int)($_GET['bulan'] ?? date('n'));
$tahun = (int)($_GET['tahun'] ?? date('Y'));
if ($bulan < 1 || $bulan > 12) $bulan = (int)date('n');
if ($tahun < 2000 || $tahun > 2100) $tahun = (int)date('Y');
$namaBulan = array('', 'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember');
$stmt = $conn->prepare("SELECT p.id,p.no_struk,p.jumlah,p.metode,p.keterangan,p.tanggal_bayar,s.nisn,s.nama,s.kelas,j.nama AS jenis,t.periode,t.tahun
FROM pembayaran p
JOIN tagihan t ON t.id=p.tagihan_id
JOIN siswa s ON s.id=t.siswa_id
JOIN jenis_pembayaran j ON j.id=t.jenis_id
WHERE MONTH(p.tanggal_bayar)=? AND YEAR(p.tanggal_bayar)=?
ORDER BY p.tanggal_bayar ASC,p.id ASC");
$stmt->bind_param("ii", $bulan, $tahun);
$stmt->execute();
$data = $stmt->get_result();
$rows=[];$total=0;$jumlah=0;$siswaUnik=[];
while($r=$data->fetch_assoc()){ $rows[]=$r; $total+=(float)$r['jumlah']; $jumlah++; $siswaUnik[$r['nisn']]=true; }
$jumlahSiswa=count($siswaUnik);
?>
